--- motion.ts ---
/**
 * Ink Signal motion vocabulary — shared JS curves/durations.
 * Keep in sync with CSS tokens in `app/globals.css` (@theme).
 *
 * Three intentional beats only:
 * 1. Enter / reveal
 * 2. Theme transition
 * 3. Hover / press
 */

/** Strong ease-out (Emil) — UI response, enter, theme icon morph */
export const easeOut = [0.23, 1, 0.32, 1] as const;

/** Slightly rounder expo for section reveal / intro dissolve */
export const easeOutExpo = [0.16, 1, 0.3, 1] as const;

/** Soft ease-out for color / background theme crossfade */
export const easeOutQuad = [0.25, 1, 0.5, 1] as const;

export const duration = {
  /** Press / tap feedback */
  press: 0.14,
  /** Hover color / lift */
  hover: 0.16,
  /** Theme surface + icon morph */
  theme: 0.24,
  /** Header / chrome enter */
  chromeEnter: 0.4,
  /** Home intro stagger children */
  introItem: 0.42,
  /** Scroll reveal sections */
  reveal: 0.42,
} as const;

export const introStagger = {
  staggerChildren: 0.055,
  delayChildren: 0.03,
} as const;
--- home intro ---
"use client";

import Image from "next/image";
import { motion, useReducedMotion } from "motion/react";
import {
  EnvelopeSimple,
  GithubLogo,
  LinkedinLogo,
  XLogo,
} from "@/components/icons";
import { duration, easeOutExpo, introStagger } from "@/lib/motion";
import { site } from "@/lib/site";

const SOCIAL_ICONS = {
  X: XLogo,
  GitHub: GithubLogo,
  LinkedIn: LinkedinLogo,
  Email: EnvelopeSimple,
} as const;

/** One authored enter beat: short stagger, soft blur dissolve. */
const container = {
  hidden: {},
  show: { transition: introStagger },
};

const item = {
  hidden: { opacity: 0, y: 8, filter: "blur(3px)" },
  show: {
    opacity: 1,
    y: 0,
    filter: "blur(0px)",
    transition: { duration: duration.introItem, ease: easeOutExpo },
  },
};

const reducedItem = {
  hidden: { opacity: 0 },
  show: {
    opacity: 1,
    transition: { duration: 0.18, ease: easeOutExpo },
  },
};

const [givenName, ...familyParts] = site.name.split(" ");
const familyName = familyParts.join(" ");

export function HomeIntro() {
  const reduce = useReducedMotion();
  const variants = reduce ? reducedItem : item;

  return (
    <motion.section
      aria-labelledby="home-intro-heading"
      className="home-intro"
      data-home-viewport="brand"
      variants={container}
      initial={reduce ? false : "hidden"}
      animate="show"
    >
      {/* Restrained atmospheric plane — ink depth + amber signal */}
      <div className="home-intro-atmosphere" aria-hidden="true" />

      <div className="home-intro-inner">
        <motion.div variants={variants} className="home-intro-mark">
          <Image
            src={site.avatar}
            alt=""
            width={40}
            height={40}
            priority
            className="home-intro-mark-img"
          />
        </motion.div>

        <motion.h1
          variants={variants}
          id="home-intro-heading"
          className="home-intro-title"
        >
          <span className="home-intro-given">{givenName}</span>
          {familyName ? (
            <span className="home-intro-family">{familyName}</span>
          ) : null}
        </motion.h1>

        <motion.p variants={variants} className="home-intro-positioning">
          {site.positioning}
        </motion.p>

        <motion.ul variants={variants} className="home-intro-socials">
          {site.socials.map((social) => {
            const Icon = SOCIAL_ICONS[social.label];
            return (
              <li key={social.label}>
                <a
                  href={social.href}
                  aria-label={social.label}
                  {...(social.href.startsWith("mailto:")
                    ? {}
                    : { target: "_blank", rel: "noopener noreferrer" })}
                  className="icon-chip"
                >
                  <Icon size={15} aria-hidden />
                </a>
              </li>
            );
          })}
        </motion.ul>
      </div>
    </motion.section>
  );
}
--- reveal ---
"use client";

import { motion, useReducedMotion } from "motion/react";
import { duration, easeOutExpo } from "@/lib/motion";

/**
 * Quiet scroll reveal — one rise-and-fade as the section enters view.
 * Reduced motion: opacity only, shorter, no translate.
 */
export function Reveal({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) {
  const reduce = useReducedMotion();

  return (
    <motion.div
      className={className}
      initial={reduce ? { opacity: 0 } : { opacity: 0, y: 8 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-48px" }}
      transition={{
        duration: reduce ? 0.18 : duration.reveal,
        ease: easeOutExpo,
      }}
    >
      {children}
    </motion.div>
  );
}
--- header ---
"use client";

import Link from "next/link";
import Image from "next/image";
import { usePathname } from "next/navigation";
import { motion, useReducedMotion } from "motion/react";
import { FOCUSABLE_CHROME } from "@/lib/a11y";
import { duration, easeOut } from "@/lib/motion";
import { PRIMARY_NAV } from "@/lib/nav";
import { site } from "@/lib/site";
import { ThemeToggle } from "@/components/theme-toggle";

/** P4 nav-chrome r2 — asymmetric rail + quiet rule (critic: bar won r1). */
export function SiteHeader() {
  const pathname = usePathname();
  const reduce = useReducedMotion();

  return (
    <motion.header
      className="site-header pointer-events-none sticky top-0 z-30"
      initial={reduce ? { opacity: 0 } : { opacity: 0, y: -6 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{
        duration: reduce ? 0.18 : duration.chromeEnter,
        ease: easeOut,
      }}
    >
      <div className="site-header-rail pointer-events-auto">
        <Link
          href="/"
          aria-label={`${site.name} — Home`}
          className="header-brand group flex min-h-8 items-center gap-2.5 no-underline"
        >
          <Image
            src={site.avatar}
            alt=""
            width={24}
            height={24}
            className="header-avatar-img size-6 rounded-full"
          />
          <span className="header-handle hidden text-[13px] font-medium tracking-[-0.015em] text-foreground min-[420px]:inline">
            {site.handle}
          </span>
        </Link>

        <div className="site-header-end">
          <nav
            aria-label={FOCUSABLE_CHROME.primaryNavLabel}
            className="site-nav"
          >
            {PRIMARY_NAV.map((item) => {
              const active =
                item.href === "/"
                  ? pathname === "/"
                  : pathname.startsWith(item.href);

              return (
                <Link
                  key={item.href}
                  href={item.href}
                  aria-current={active ? "page" : undefined}
                  data-active={active}
                  className="nav-item"
                >
                  <span className="nav-item-label">{item.label}</span>
                  {active && !reduce ? (
                    <motion.span
                      layoutId="nav-active-signal"
                      className="nav-item-signal"
                      transition={{
                        type: "spring",
                        duration: 0.36,
                        bounce: 0.1,
                      }}
                      aria-hidden
                    />
                  ) : active ? (
                    <span className="nav-item-signal" aria-hidden />
                  ) : null}
                </Link>
              );
            })}
          </nav>

          <ThemeToggle />
        </div>
      </div>
    </motion.header>
  );
}
