/*
  Backdrop — Ink Signal atmosphere (P2).
  End-to-end depth: vignette + amber signal wash + structural grid/dots + film grain.
  No purple wash; grain/grid must read in both themes and on mobile.
*/
.site-backdrop {
  pointer-events: none;
  position: fixed;
  inset: 0;
  z-index: -1;
  overflow: hidden;
  background-color: var(--color-background);
  background-image:
    /* Edge vignette — pulls focus into the reading plane */
    radial-gradient(
      ellipse 92% 78% at 50% 38%,
      transparent 42%,
      var(--vignette-color) 100%
    ),
    /* Amber signal wash — top-left hero pool */
    radial-gradient(
      110% 65% at 28% -8%,
      color-mix(in srgb, var(--color-accent) 14%, transparent),
      transparent 58%
    ),
    /* Warm ink corner wash */
    radial-gradient(
      70% 50% at 0% 85%,
      var(--ink-wash),
      transparent 58%
    ),
